// ═══ throw — CREATES and THROWS an exception at runtime ═══
public void withdraw(BigDecimal amount) {
    if (amount.signum() <= 0) {
        throw new IllegalArgumentException("Amount must be positive: " + amount);
        //   ^^^^^  STATEMENT inside method body
        //          Creates exception object + throws it
        //          Method execution STOPS here
        //          Exception propagates up the call stack
    }
    if (balance.compareTo(amount) < 0) {
        throw new InsufficientBalanceException(balance, amount);
        // Can throw different exceptions based on conditions
    }
    balance = balance.subtract(amount);
    // This line only executes if NO throw happened above
}

// ═══ throws — DECLARES exceptions in method signature ═══
public String readTradeFile(String path) throws IOException, FileNotFoundException {
    //                                    ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
    //                                    METHOD SIGNATURE — warns callers!
    //                                    Multiple exceptions, comma-separated
    return Files.readString(Path.of(path));
    // If IOException occurs → propagates to caller
    // Caller MUST handle (try-catch or declare throws) because IOException is CHECKED
}

// ═══ BOTH together — most common pattern ═══
public Trade parseTrade(String line) throws TradeParseException {
    //                               ^^^^^^ DECLARES: might throw
    try {
        String[] parts = line.split(",");
        return new Trade(parts[0], parts[1], new BigDecimal(parts[2]));
    } catch (Exception e) {
        throw new TradeParseException("Failed to parse: " + line, e);
        // ^^^^^ THROWS: actually creates and throws
    }
}
