package com.bank.throwdemo.service;

import com.bank.throwdemo.exception.TradeFileException;
import java.math.BigDecimal;
import java.nio.file.*;

public class TradeService {

    // ═══ throw ONLY (unchecked — no throws needed in signature) ═══
    public void withdraw(BigDecimal balance, BigDecimal amount) {
        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
            // throw = CREATES exception + THROWS it NOW
            // No "throws" in method signature — unchecked!
        }
        if (balance.compareTo(amount) < 0) {
            throw new RuntimeException("Insufficient balance: " + balance + " < " + amount);
        }
    }

    // ═══ BOTH throw AND throws (checked exception) ═══
    public String readTradeFile(String path) throws TradeFileException {
        //                                   ^^^^^^^^^^^^^^^^^^^^^^ DECLARES: might throw
        try {
            return Files.readString(Path.of(path));
        } catch (java.io.IOException e) {
            throw new TradeFileException("Cannot read: " + path, e);
            // ^^^^^ CREATES + THROWS checked exception
        }
    }

    // ═══ throws MULTIPLE exceptions ═══
    public void processAndStore(String filePath) throws TradeFileException, IllegalStateException {
        //                                        ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
        //                                        Two exceptions declared
        String data = readTradeFile(filePath);  // might throw TradeFileException
        if (data.isBlank()) {
            throw new IllegalStateException("Empty file!");  // unchecked — throws optional but documented
        }
    }

    // ═══ Re-throw pattern ═══
    public void validateAndProcess(BigDecimal amount) {
        try {
            withdraw(BigDecimal.ZERO, amount);
        } catch (RuntimeException e) {
            // Log, then re-throw:
            System.err.println("Validation failed: " + e.getMessage());
            throw e;  // RE-THROW the same exception — no "new"
        }
    }
}
```

```java
// ─── File: src/test/java/com/bank/throwdemo/ThrowVsThrowsTest.java ───
package com.bank.throwdemo;

import com.bank.throwdemo.exception.TradeFileException;
import com.bank.throwdemo.service.TradeService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ThrowVsThrowsTest {

    TradeService service = new TradeService();

    // ═══ throw: creates exception at runtime ═══
    @Test
    void throw_createsException() {
        assertThatThrownBy(() -> service.withdraw(BigDecimal.ZERO, new BigDecimal("-100")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("positive");
        // throw new IllegalArgumentException() → exception CREATED and THROWN
    }

    // ═══ throws: declares checked exception — compiler forces handling ═══
    @Test
    void throws_compilerForcesHandling() {
        // service.readTradeFile("/nonexistent");
        // ↑ Without try-catch: COMPILE ERROR! Because throws TradeFileException (checked)

        assertThatThrownBy(() -> service.readTradeFile("/nonexistent/file.csv"))
            .isInstanceOf(TradeFileException.class);
    }

    // ═══ throw without throws: unchecked doesn't need signature declaration ═══
    @Test
    void throw_uncheckedNoThrowsNeeded() {
        // withdraw() has throw but NO throws in signature — unchecked!
        assertThatThrownBy(() -> service.withdraw(new BigDecimal("100"), new BigDecimal("500")))
            .isInstanceOf(RuntimeException.class)
            .hasMessageContaining("Insufficient");
    }

    // ═══ throws multiple exceptions ═══
    @Test
    void throws_multipleExceptions() throws TradeFileException {
        // processAndStore declares: throws TradeFileException, IllegalStateException
        // Caller must handle TradeFileException (checked)
        // IllegalStateException is unchecked — optional to handle
        assertThatThrownBy(() -> service.processAndStore("/nonexistent"))
            .isInstanceOf(TradeFileException.class);
    }

    // ═══ Re-throw: throw without new ═══
    @Test
    void rethrow_sameException() {
        assertThatThrownBy(() -> service.validateAndProcess(new BigDecimal("-50")))
            .isInstanceOf(IllegalArgumentException.class);
        // catch + throw e → re-throws the SAME exception (no new object)
    }

    // ═══ SUMMARY ═══
    @Test
    void summary() {
        // throw = INSIDE method body. Creates exception. One at a time.
        //   throw new IOException("fail");
        //   throw existingException;  (re-throw)

        // throws = IN method signature. Declares what MIGHT be thrown. Multiple allowed.
        //   public void read() throws IOException, SQLException { }

        // throw followed by OBJECT: throw new X()
        // throws followed by CLASS NAMES: throws X, Y
        assertThat(true).isTrue();
    }
}
